// Flat config for apps/web (ESLint 9). Ported from the postiz-absorption branch.
// Minimal gate: JS recommended + TS recommended + react-hooks.
// `tsc -b` (strict + noUnusedLocals) stays the type gate; this file gates lint only.
// App code gets browser globals only, so a stray `process.env` is caught here too.
import js from '@eslint/js';
import globals from 'globals';
import tseslint from 'typescript-eslint';
import reactHooks from 'eslint-plugin-react-hooks';

export default tseslint.config(
  // src/contracts/ is generated by contracts/gen.sh and is not linted.
  { ignores: ['dist/**', 'build/**', 'coverage/**', 'node_modules/**', 'src/contracts/**'] },
  js.configs.recommended,
  reactHooks.configs['recommended-latest'],
  ...tseslint.configs.recommended,
  {
    files: ['src/**/*.{ts,tsx}'],
    languageOptions: { globals: { ...globals.browser } },
    rules: {
      'no-console': 'warn',
      '@typescript-eslint/no-unused-vars': [
        'error',
        { argsIgnorePattern: '^_', varsIgnorePattern: '^_', destructuredArrayIgnorePattern: '^_' },
      ],
      '@typescript-eslint/no-explicit-any': 'off',
    },
  },
  {
    // Tooling files run in Node.
    files: ['*.{js,ts}'],
    languageOptions: { globals: { ...globals.node } },
  },
);
